<?php header("Content-Type: application/json; charset=UTF-8"); require_once "db.php"; try { $user_id = intval($_GET["user_id"] ?? 0); if ($user_id <= 0) { throw new Exception("Invalid donor ID."); } /* * Automatically mark expired food as Expired. */ $expireSql = " UPDATE food_donations SET status = 'Expired' WHERE user_id = ? AND expiry_datetime <= NOW() AND status IN ('Available', 'Claimed') "; $expireStmt = $conn->prepare($expireSql); if (!$expireStmt) { throw new Exception("Unable to prepare expiry query."); } $expireStmt->bind_param("i", $user_id); $expireStmt->execute(); $expireStmt->close(); /* * Get donor's food. * * Only food whose expiry time has NOT passed is displayed. * * A claim can be joined because food_claims contains: * donation_id * receiver_name * receiver_phone * message */ $sql = " SELECT f.donation_id, f.user_id, f.donor_name, f.contact, f.food_type, f.quantity, f.pickup_datetime, f.expiry_datetime, f.locality, f.location_name, f.details, f.status, f.created_at, c.claim_id, c.receiver_id, c.receiver_name, c.receiver_phone, c.message AS receiver_message, c.status AS claim_status, c.created_at AS claim_created_at FROM food_donations f LEFT JOIN food_claims c ON f.donation_id = c.donation_id WHERE f.user_id = ? AND f.expiry_datetime > NOW() ORDER BY CASE WHEN f.status = 'Claimed' THEN 0 ELSE 1 END, f.pickup_datetime ASC ";$stmt = $conn->prepare($sql); if (!$stmt) { throw new Exception("Unable to prepare food query."); } $stmt->bind_param("i", $user_id); if (!$stmt->execute()) { throw new Exception("Unable to load donor food."); } $result = $stmt->get_result(); $foods = []; while ($row = $result->fetch_assoc()) { $row["pickup_location"] = !empty($row["location_name"]) ? $row["location_name"] : $row["locality"]; $row["is_claimed"] = ($row["status"] === "Claimed"); $foods[] = $row; } $stmt->close(); $conn->close(); echo json_encode([ "success" => true, "data" => $foods ]); } catch (Throwable $e) { http_response_code(500); echo json_encode([ "success" => false, "message" => $e->getMessage() ]); } ?>